effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat7;
bvec2 u_xlatb13;
bvec2 u_xlatb14;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.x = acScreenNorm.x;
    u_xlat1.x = u_xlat1.x + -0.5;
    u_xlat7.xy = _resolution.xy / _resolution.yx;
    u_xlat1.x = u_xlat7.x * u_xlat1.x;
    u_xlat1.y = (-acScreenNorm.y) + 0.5;
    u_xlat1.xy = u_xlat1.xy + (-vec2(_offset.x, _offset.y));
    u_xlat2.xyz = vec3(_angle, _scale.x, _scale.y) * vec3(0.0174532998, 10.0, 10.0);
    u_xlat3.x = sin(u_xlat2.x);
    u_xlat4.x = cos(u_xlat2.x);
    u_xlat5.x = cos((-u_xlat2.x));
    u_xlat2.x = sin((-u_xlat2.x));
    u_xlat4.y = u_xlat3.x;
    u_xlat1.w = dot(u_xlat1.xy, u_xlat4.xy);
    u_xlat4.z = u_xlat2.x;
    u_xlat1.x = dot(u_xlat1.yx, u_xlat4.xz);
    u_xlat1.xy = u_xlat2.zy * u_xlat1.xw;
    u_xlat3.x = floor(u_xlat1.y);
    u_xlat1.x = floor(u_xlat1.x);
    u_xlat3.y = _seed * 3937.72485 + u_xlat1.x;
    u_xlat7.x = dot(u_xlat3.xy, vec2(719.309998, 178.233002));
    u_xlat7.x = u_xlat7.x * 0.318471313;
    u_xlatb19 = u_xlat7.x>=(-u_xlat7.x);
    u_xlat7.x = fract(abs(u_xlat7.x));
    u_xlat7.x = (u_xlatb19) ? u_xlat7.x : (-u_xlat7.x);
    u_xlat7.x = u_xlat7.x * 3.1400001;
    u_xlat7.x = sin(u_xlat7.x);
    u_xlat7.x = u_xlat7.x * 33758.5469;
    u_xlat1.y = fract(u_xlat7.x);
    u_xlat1.xy = u_xlat1.xy + vec2(0.5, -0.5);
    u_xlat7.x = u_xlat1.y * _strength;
    u_xlat7.x = u_xlat7.x * 12.5663605;
    u_xlat7.x = _rotation * 0.0174532998 + u_xlat7.x;
    u_xlat19 = u_xlat3.x + 0.5;
    u_xlat2.x = u_xlat19 / u_xlat2.y;
    u_xlat2.y = u_xlat1.x / u_xlat2.z;
    u_xlat4.w = u_xlat5.x;
    u_xlat3.x = dot(u_xlat2.yx, u_xlat4.zw);
    u_xlat3.y = dot(u_xlat2.xy, u_xlat4.yw);
    u_xlat1.xw = u_xlat3.xy + vec2(_offset.x, _offset.y);
    u_xlat2.xy = u_xlat1.xw * u_xlat7.yy + vec2(0.5, 0.5);
    u_xlat2.z = (-u_xlat2.y) + 1.0;
    u_xlat1.xz = (-u_xlat2.xz) + acScreenNorm.xy;
    u_xlat3.x = sin(u_xlat7.x);
    u_xlat4.x = cos(u_xlat7.x);
    u_xlat5.x = sin((-u_xlat7.x));
    u_xlat5.y = u_xlat4.x;
    u_xlat5.z = u_xlat3.x;
    u_xlat3.x = dot(u_xlat1.xz, u_xlat5.yz);
    u_xlat3.y = dot(u_xlat1.xz, u_xlat5.xy);
    u_xlat1.xy = u_xlat2.xz + u_xlat3.xy;
    u_xlatb13.xy = lessThan(u_xlat1.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlat2.xy = fract(u_xlat1.xy);
    u_xlatb14.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat1.xyxy).xy;
    u_xlat3.xy = (-u_xlat2.xy) + vec2(1.0, 1.0);
    {
        vec4 hlslcc_movcTemp = u_xlat1;
        hlslcc_movcTemp.x = (u_xlatb14.x) ? u_xlat3.x : u_xlat1.x;
        hlslcc_movcTemp.y = (u_xlatb14.y) ? u_xlat3.y : u_xlat1.y;
        u_xlat1 = hlslcc_movcTemp;
    }
    {
        vec4 hlslcc_movcTemp = u_xlat1;
        hlslcc_movcTemp.x = (u_xlatb13.x) ? u_xlat2.x : u_xlat1.x;
        hlslcc_movcTemp.y = (u_xlatb13.y) ? u_xlat2.y : u_xlat1.y;
        u_xlat1 = hlslcc_movcTemp;
    }
    u_xlat1 = texture(inputImg, u_xlat1.xy);
    u_xlat1 = u_xlat0.wwww * u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
